// This function generates a random number between 1 and 6
function getRandomNumber() {
    return Math.floor(Math.random() * 6) + 1;
}
// Example usage:
let randomNumber = getRandomNumber();
console.log(randomNumber); // Output: A random number between 1 and 6
// Note: This function uses the built-in Math.random() method in JavaScript to generate a random value, and then converts it to an integer using Math.floor(). It then adds 1 to ensure the output is always between 1 and 6 inclusive.user

